const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the two locations
  const antakya = ee.Geometry.Point([36.2066, 36.1608]); // Antakya coordinates
  const altinozu = ee.Geometry.Point([36.1167, 36.2333]); // Altınözü coordinates

  // Buffer the points to get small regions
  const antakya_region = antakya.buffer(1000); // 1km buffer
  const altinozu_region = altinozu.buffer(1000); // 1km buffer

  // Define date ranges
  const startDate1 = '2023-02-21';
  const endDate1 = '2023-02-28'; // Small window around target date
  const startDate2 = '2023-04-30';
  const endDate2 = '2023-05-07'; // Small window around target date

  // Get VIIRS Nighttime Lights data
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG');

  // Filter for the two periods
  const period1 = viirs.filterDate(startDate1, endDate1);
  const period2 = viirs.filterDate(startDate2, endDate2);

  // Check if collections have data
  const period1Size = period1.size().getInfo();
  const period2Size = period2.size().getInfo();

  console.log(`Period 1 (Feb) Images: ${period1Size}`);
  console.log(`Period 2 (Apr) Images: ${period2Size}`);

  if (period1Size === 0 || period2Size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the median composite for each period
  const img1 = period1.median();
  const img2 = period2.median();

  // Extract radiance values for both locations
  const antakya_p1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: antakya_region,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const antakya_p2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: antakya_region,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const altinozu_p1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: altinozu_region,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const altinozu_p2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: altinozu_region,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`Antakya P1: ${antakya_p1?.toFixed(3)}, P2: ${antakya_p2?.toFixed(3)}`);
  console.log(`Altınözü P1: ${altinozu_p1?.toFixed(3)}, P2: ${altinozu_p2?.toFixed(3)}`);

  // Check for valid data
  if (antakya_p1 === null || antakya_p2 === null || altinozu_p1 === null || altinozu_p2 === null) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate increases
  const antakya_increase = antakya_p2 - antakya_p1;
  const altinozu_increase = altinozu_p2 - altinozu_p1;

  console.log(`Antakya Increase: ${antakya_increase?.toFixed(3)}`);
  console.log(`Altınözü Increase: ${altinozu_increase?.toFixed(3)}`);

  // Validate values are reasonable (radiance shouldn't be negative or extremely high)
  if (antakya_increase === null || altinozu_increase === null || 
      Math.abs(antakya_increase) > 100 || Math.abs(altinozu_increase) > 100) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare increases
  if (antakya_increase > altinozu_increase) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
